use crate::dispatch::{
    rendering_of, rendering_of_loaded, rendering_of_macro, LinkedRow, LoadedDoor,
};
use busbar_contract::abi::sdk::door::MacroDoor;

#[test]
fn actual_mcp_function_macro_and_loaded_rows_preserve_the_same_door_and_statement() {
    let door = crate::actual_mcp::door;
    // SAFETY: actual_mcp holds the validated real MCP image for the process lifetime.
    // MCP's descriptor is generated by SDK plugin_door!, with static Statement lists
    // and operation table; this wrapper returns that same descriptor without alteration.
    let macro_door = unsafe { MacroDoor::__from_door_macro(door) };
    let restated = unsafe { LoadedDoor::from_raw(crate::dispatch::load::raw(door)) };
    assert_eq!(door as usize, macro_door.door_fn() as usize);
    let by_fn = LinkedRow::of(door).expect("actual function door states itself");
    let by_macro = LinkedRow::of_macro(macro_door).expect("actual macro handle states itself");
    let by_loaded = LinkedRow::of_loaded(restated).expect("actual loaded door states itself");
    assert_eq!(by_fn.statement, by_macro.statement);
    assert_eq!(by_fn.statement, by_loaded.statement);
    assert_eq!(by_fn.door as usize, by_macro.door as usize);
    assert_eq!(by_fn.door as usize, by_loaded.door as usize);
    assert_eq!(
        rendering_of(door).unwrap(),
        rendering_of_macro(macro_door).unwrap()
    );
    assert_eq!(
        rendering_of(door).unwrap(),
        rendering_of_loaded(restated).unwrap()
    );

    let manifest =
        crate::LinkedPlugin::first_party_door("plane", "busbar-plane-mcp", "tools", door).manifest;
    let linked = crate::PluginRegistry::empty()
        .link(vec![crate::LinkedPlugin::door(manifest.clone(), door)])
        .expect("the actual function door links");
    let linked_macro = crate::PluginRegistry::empty()
        .link(vec![crate::LinkedPlugin::of_macro(
            manifest.clone(),
            macro_door,
        )])
        .expect("the actual macro handle links");
    let linked_loaded = crate::PluginRegistry::empty()
        .link(vec![crate::LinkedPlugin::of_loaded(manifest, restated)])
        .expect("the actual loaded door links");
    let entry = |registry: &crate::PluginRegistry| registry.linked()[0].door().map(|d| d as usize);
    assert!(entry(&linked).is_some());
    assert_eq!(entry(&linked), entry(&linked_macro));
    assert_eq!(entry(&linked), entry(&linked_loaded));
}

#[test]
fn actual_dropped_mcp_bytes_enter_the_production_staging_path_once() {
    use crate::dispatch::{
        load_dropped_bytes, Bind, ConnTable, DispatchConfig, Dispatcher, NoSink,
    };
    use std::sync::Arc;
    let bytes = std::fs::read(crate::actual_mcp::cdylib()).expect("read the actual MCP image");
    let stated = rendering_of(crate::actual_mcp::door).expect("actual MCP statement");
    let dispatcher = Dispatcher::new(DispatchConfig::default());
    let before = crate::stage::STAGED_HERE.with(std::cell::Cell::get);
    let plugin = load_dropped_bytes::<crate::dispatch::kinds::plane::Plane>(
        &bytes,
        "actual-mcp-staged",
        &stated,
        Bind {
            instance: Arc::from("actual-mcp-staged"),
            max_inflight_cap: 8,
            sink: Arc::new(NoSink),
            dispatcher: dispatcher.adopter(),
            conns: ConnTable::Probe,
        },
    )
    .expect("actual MCP bytes load through production staging");
    let staged = crate::stage::STAGED_HERE.with(std::cell::Cell::get) - before;
    assert_eq!(
        staged, 1,
        "the actual dropped image must stage once rather than load its build path"
    );
    drop(plugin);
}
